preConditionHook:
// FRACTAL BOX BREAKOUT (Brian's notes ON-50, pp.59-60). The four most recent
// pivots, oldest to newest, are low, high, low, high with the last two inside
// the range of the first two (inclusive): a contracting box whose edges are
// the last two pivots. Long on the FIRST close above the box since its newest
// pivot printed, short on the first close below. The mirror order high, low,
// high, low with the same containment also counts (Brian 2026-11-05). A newer
// pivot replaces the pattern, since it must be the four most recent. The p.60
// fade is this rule with the per-placement flip.
// PIVOT SEQUENCE -- one inlined form, copied verbatim into every rule of the
// own-rules slice 02 (FractalBoxBreakout, LateFractalFade,
// FractalOrderLowHighHigh, FractalLegSlopeDecay, FractalMovePullbackContraction).
// The merged, NEWEST-FIRST list of the confirmed swing pivots of `strength`
// whose bars lie in the last `lookback` bars, highs and lows in one sequence and
// NON-ALTERNATING (two highs may follow each other). Slot 1 is the newest:
// pT = +1 swing high / -1 swing low, pV = its price, pB = its bars-ago. Only
// the newest four are kept in slots; pivN counts every pivot found, and a
// rule needing m pivots tests pivN >= m -- prices are never trusted through a
// sentinel.
//
// Pivot test hand-rolled as in SwingPivotTarget, because the register lists
// SwingHigh's Occurrence 3+ as unmeasured. MEASURED (EL_Swing_Probe.txt): the
// pivot bar is AT OR ABOVE the `strength` OLDER bars and STRICTLY ABOVE the
// `strength` NEWER bars -- the newer bars are the smaller k and take el_gt /
// el_lt, the older el_ge / el_le; confirmation lag exactly `strength` bars, so
// the newest possible pivot has bars-ago `strength`; candidate offsets
// strength .. lookback - 1, the neighbourhood reaching `strength` bars past the
// window, so the deepest bar touched is lookback - 1 + strength. The low side's tie
// sense mirrors the measured high side.
//
// A bar that is BOTH a swing high and a swing low counts as both (Brian
// 2026-11-05), ordered by the bar's colour: a green bar (close > open) made its
// low first and its high second, so in this newest-first list its high is
// pushed first; any other bar is read as red, high followed by low, so its low is
// pushed first. Both entries carry the same bars-ago. No early break,
// matching the twin. Scratch is declared in localVariables (double placement);
// the loop counters are block-scoped.
pivStrength = (int)strength;
pivWindow = (int)lookback;
pivN = 0;
pT1 = 0;
pT2 = 0;
pT3 = 0;
pT4 = 0;
pV1 = 0.0;
pV2 = 0.0;
pV3 = 0.0;
pV4 = 0.0;
pB1 = 0;
pB2 = 0;
pB3 = 0;
pB4 = 0;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    pushA = 0;
    pushB = 0;
    if (okHi && okLo) {
        if (el_gt(close[j], open[j])) {
            pushA = 1;
            pushB = -1;
        }
        else {
            pushA = -1;
            pushB = 1;
        }
    }
    else if (okHi)
        pushA = 1;
    else if (okLo)
        pushA = -1;
    for (int m = 1; m <= 2; ++m) {
        if (m == 1)
            curT = pushA;
        else
            curT = pushB;
        if (curT != 0) {
            if (curT == 1)
                curV = high[j];
            else
                curV = low[j];
            pivN = pivN + 1;
            if (pivN == 1) { pT1 = curT; pV1 = curV; pB1 = j; }
            if (pivN == 2) { pT2 = curT; pV2 = curV; pB2 = j; }
            if (pivN == 3) { pT3 = curT; pV3 = curV; pB3 = j; }
            if (pivN == 4) { pT4 = curT; pV4 = curV; pB4 = j; }
        }
    }
}
boxPat = false;
boxHi = 0.0;
boxLo = 0.0;
if (pivN >= 4) {
    if (pT4 == -1 && pT3 == 1 && pT2 == -1 && pT1 == 1) {
        boxPat = el_ge(pV2, pV4) && el_le(pV2, pV3) && el_ge(pV1, pV4) && el_le(pV1, pV3);
        boxHi = pV1;
        boxLo = pV2;
    }
    if (pT4 == 1 && pT3 == -1 && pT2 == 1 && pT1 == -1) {
        boxPat = el_ge(pV2, pV3) && el_le(pV2, pV4) && el_ge(pV1, pV3) && el_le(pV1, pV4);
        boxHi = pV2;
        boxLo = pV1;
    }
}
// FIRST close outside: no close since the newest pivot's bar (bars 1 ..
// pB1 - 1) has left the box.
firstOut = true;
if (boxPat) {
    for (int i = 1; i <= pB1 - 1; ++i) {
        if (el_gt(close[i], boxHi) || el_lt(close[i], boxLo)) firstOut = false;
    }
}
